const BRAND_MARK=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 128 128"><defs><linearGradient id="cap" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#35D7EA"/><stop offset=".52" stop-color="#5368F5"/><stop offset="1" stop-color="#8C4DFA"/></linearGradient><linearGradient id="book" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#42D8E9"/><stop offset="1" stop-color="#7952F5"/></linearGradient></defs><path d="M12 39 64 15l52 24-52 24L12 39Z" fill="url(#cap)"/><path d="M31 49v21c18 13 48 13 66 0V49L64 64 31 49Z" fill="#263A89"/><path d="M108 43v31" stroke="#48D7E8" stroke-width="4" stroke-linecap="round"/><circle cx="108" cy="79" r="5" fill="#48D7E8"/><path d="M64 80C48 67 28 68 15 79v28c17-10 34-8 49 5 15-13 32-15 49-5V79C100 68 80 67 64 80Z" fill="url(#book)"/><path d="M64 80v32M20 85c12-5 25-3 36 4M108 85c-12-5-25-3-36 4" fill="none" stroke="#fff" stroke-width="3" stroke-linecap="round"/><path d="m64 28 3 7 7 3-7 3-3 7-3-7-7-3 7-3 3-7Z" fill="#fff"/></svg>`;
function Field(p:{value:string;onChangeText:(v:string)=>void;placeholder:string;multiline?:boolean;secure?:boolean}){return <TextInput value={p.value} onChangeText={p.onChangeText} placeholder={p.placeholder} placeholderTextColor="#8992A8" secureTextEntry={p.secure} multiline={p.multiline} style={[s.field,p.multiline&&{height:86,textAlignVertical:"top"}]}/>}
function Button(p:{label:string;onPress:()=>void;disabled?:boolean;light?:boolean}){return <Pressable disabled={p.disabled} onPress={p.onPress} style={[s.button,p.light&&{backgroundColor:C.pale},p.disabled&&{opacity:.5}]}><Text style={[s.buttonText,p.light&&{color:C.purple}]}>{p.label}</Text></Pressable>}
