 const nav:{id:Tab;label:string;icon:string}[]=[{id:"home",label:"Home",icon:"⌂"},{id:"student",label:"Class",icon:"▦"},{id:"assignments",label:"Tasks",icon:"▤"},{id:"exams",label:"Exams",icon:"✓"},{id:"results",label:"Results",icon:"◉"},{id:"teacher",label:"Teach",icon:"♙"},{id:"ai",label:"Academia AI",icon:"✦"},{id:"keep",label:"Academia Keep",icon:"▣"},{id:"meet",label:"Meet & Zoom",icon:"◉"},{id:"admin",label:"Admin",icon:"⚙"}];
