 {tab==="home"&&<><View style={s.hero}><View style={s.heroBrandRow}><View style={s.heroSpark}><SvgXml xml={BRAND_MARK} width={40} height={40}/></View><Text style={s.heroBrandText}>ACADEMIA STUDIO</Text></View><Text style={s.eyebrow}>YOUR ACADEMIC WORKSPACE</Text><Text style={s.title}>Welcome back, {profile?.display_name||user?.email?.split("@")[0]||"Learner"}</Text><Text style={s.sub}>Everything you need to learn, teach and stay on track — all in one place.</Text><View style={s.heroPill}><Text style={s.heroPillText}>{teacher?"TEACHER WORKSPACE":"STUDENT WORKSPACE"}</Text></View></View><View style={s.stats}><Card><Text style={s.number}>{classes.length}</Text><Text style={s.meta}>Classrooms</Text></Card><Card><Text style={s.number}>{assignments.length}</Text><Text style={s.meta}>Assignments</Text></Card><Card><Text style={s.number}>{exams.length}</Text><Text style={s.meta}>Exams</Text></Card></View><Card><Text style={s.cardTitle}>Your account</Text><Text style={s.body}>{profile?.role??"student"} account · {teacher?"Teacher tools enabled":"Student workspace"}</Text></Card><Text style={s.section}>Upcoming assignments</Text>{assignments.slice(0,4).map(a=><Card key={a.id}><Text style={s.cardTitle}>{a.title}</Text><Text style={s.body}>{a.instructions||"No additional instructions."}</Text><Text style={s.meta}>Due {a.due_at?new Date(a.due_at).toLocaleString():"date not set"}</Text></Card>)}{!assignments.length?<Text style={s.empty}>No assignments yet. Join a classroom to get started.</Text>:null}</>}
 {tab==="student"&&<><View style={s.portalHero}><Text style={s.eyebrow}>STUDENT LEARNING HUB</Text><Text style={s.portalTitle}>Your Student Portal</Text><Text style={s.portalSub}>Your classrooms, coursework and upcoming exams — organised in one place.</Text><View style={s.portalStats}><View style={s.portalStat}><Text style={s.portalStatNumber}>{classes.length}</Text><Text style={s.portalStatLabel}>Classes</Text></View><View style={s.portalStat}><Text style={s.portalStatNumber}>{assignments.length}</Text><Text style={s.portalStatLabel}>Tasks</Text></View><View style={s.portalStat}><Text style={s.portalStatNumber}>{exams.length}</Text><Text style={s.portalStatLabel}>Exams</Text></View></View></View><Card><Text style={s.cardTitle}>＋ Join a new classroom</Text><Text style={s.body}>Enter the invitation code shared by your teacher to access a course.</Text><Field value={joinCode} onChangeText={setJoinCode} placeholder="Enter classroom code"/><Button label={busy?"Joining…":"Join classroom"} onPress={join} disabled={busy||!joinCode.trim()}/></Card><View style={s.portalSectionHead}><View><Text style={s.section}>My classrooms</Text><Text style={s.portalHint}>Your active learning spaces</Text></View><Pressable onPress={()=>loadData(user!)} style={s.refreshBtn}><Text style={s.refreshText}>↻ Refresh</Text></Pressable></View>{classes.map(c=>{const ca=assignments.filter(a=>a.classroom_id===c.id);const ce=exams.filter(e=>e.classroom_id===c.id);return <Card key={c.id}><View style={s.classCardTop}><View style={s.classIcon}><Text style={s.classIconText}>{c.name.slice(0,1).toUpperCase()}</Text></View><View style={{flex:1}}><Text style={s.cardTitle}>{c.name}</Text><Text style={s.portalHint}>{c.description||"Course classroom"}</Text></View><View style={s.classActive}><Text style={s.classActiveText}>ACTIVE</Text></View></View><View style={s.classMetrics}><View style={s.classMetric}><Text style={s.classMetricNum}>{ca.length}</Text><Text style={s.classMetricLabel}>Assignments</Text></View><View style={s.classMetric}><Text style={s.classMetricNum}>{ce.length}</Text><Text style={s.classMetricLabel}>Exams</Text></View></View><Text style={s.classCodeLabel}>CLASS INVITATION CODE</Text><Text style={s.classCode}>{c.class_code}</Text>{ca.length>0?<><Text style={s.sectionSmall}>Coursework</Text>{ca.slice(0,3).map(a=><View key={a.id} style={s.courseLine}><View style={{flex:1}}><Text style={s.courseLineTitle}>{a.title}</Text><Text style={s.portalHint}>{a.total_marks} marks · {a.due_at?"Due "+new Date(a.due_at).toLocaleDateString():"No due date"}</Text></View><Text style={s.courseArrow}>›</Text></View>)}</>:<Text style={s.portalHint}>No assignments have been published for this class yet.</Text>}{ce.length>0?<Text style={s.portalExamNote}>{ce.length} exam{ce.length===1?"":"s"} available in Exam Center</Text>:null}</Card>})}{!classes.length?<View style={s.emptyPortal}><Text style={s.emptyPortalIcon}>▦</Text><Text style={s.emptyPortalTitle}>Your learning journey starts here</Text><Text style={s.empty}>Join a classroom using the code from your teacher. Your courses and activities will appear here.</Text></View>:null}</>}
 {tab==="assignments"&&<><Text style={s.title}>Assignment Studio</Text><Text style={s.sub}>Read instructions and submit your work.</Text>{assignments.map(a=><Card key={a.id}><Text style={s.cardTitle}>{a.title}</Text><Text style={s.body}>{a.instructions||"No instructions."}</Text><Text style={s.meta}>{a.total_marks} marks</Text><Field value={answers[a.id]||""} onChangeText={v=>setAnswers(old=>({...old,[a.id]:v}))} placeholder="Write your answer…" multiline/><Button label="Submit assignment" onPress={()=>submit(a.id)} disabled={busy}/></Card>)}{!assignments.length?<Text style={s.empty}>No published assignments in your classrooms.</Text>:null}</>}
 {tab==="exams"&&<>{activeExam&&attempt?.status==="in_progress"?<><Text style={s.title}>{activeExam.title}</Text><Text style={s.sub}>{activeExam.instructions||"Answer each question. Your answers are saved as you go."}</Text><Card><Text style={s.cardTitle}>Time remaining</Text><Text style={s.number}>{Math.floor(secondsLeft/60).toString().padStart(2,"0")}:{(secondsLeft%60).toString().padStart(2,"0")}</Text><Text style={s.meta}>{questions.length} questions · {activeExam.total_marks} marks</Text></Card>{questions.map((q,i)=><Card key={q.id}><Text style={s.meta}>QUESTION {i+1} · {q.points} marks</Text><Text style={s.cardTitle}>{q.question_text}</Text>{Array.isArray(q.options)&&q.options.length&&["mcq","true_false"].includes(q.question_type)?q.options.map((opt:any,j)=>{const val=String(typeof opt==="string"?opt:opt.label??opt.value??opt.text??"");return <Pressable key={j} onPress={()=>saveExamAnswer(q,val)} style={[s.option,examAnswers[q.id]===val&&s.optionSelected]}><Text style={s.body}>{val}</Text></Pressable>}):<Field value={examAnswers[q.id]??""} onChangeText={v=>saveExamAnswer(q,v)} placeholder={q.question_type==="multiple_select"?"Enter options separated by commas":"Write your answer…"} multiline/>}</Card>)}<Button label="Submit exam" onPress={()=>Alert.alert("Submit exam","Are you sure you want to submit?",[{text:"Continue",style:"cancel"},{text:"Submit",style:"destructive",onPress:()=>finishExam(false)}])} disabled={busy}/></>:<><Text style={s.title}>Exam Center</Text><Text style={s.sub}>Start an available exam to answer questions.</Text>{exams.map(e=><Card key={e.id}><Text style={s.cardTitle}>{e.title}</Text><Text style={s.body}>{e.duration_minutes} minutes · {e.total_marks} marks</Text><Text style={s.meta}>{e.status.toUpperCase()} {e.starts_at?"· "+new Date(e.starts_at).toLocaleString():""}</Text><Button label="Start / Resume exam" onPress={()=>startExam(e)} disabled={busy||!["scheduled","live"].includes(e.status)}/></Card>)}{!exams.length?<Text style={s.empty}>No exams scheduled for your classrooms yet.</Text>:null}</>}</>}
 {tab==="results"&&<><Text style={s.title}>My Results</Text><Text style={s.sub}>Track submitted assignments, marks and teacher feedback in one place.</Text><View style={s.stats}><Card><Text style={s.number}>{studentSubmissions.length}</Text><Text style={s.meta}>Submitted</Text></Card><Card><Text style={s.number}>{studentSubmissions.filter(x=>x.status==="graded").length}</Text><Text style={s.meta}>Graded</Text></Card><Card><Text style={s.number}>{studentSubmissions.filter(x=>x.status!=="graded").length}</Text><Text style={s.meta}>Awaiting review</Text></Card></View>{studentSubmissions.map(sub=>{const a=assignments.find(x=>x.id===sub.assignment_id);return <Card key={sub.id}><View style={{flexDirection:"row",justifyContent:"space-between",alignItems:"center",flexWrap:"wrap"}}><Text style={s.cardTitle}>{a?.title??"Assignment"}</Text><View style={[s.statusPill,sub.status==="graded"?s.statusGood:s.statusPending]}><Text style={[s.statusText,sub.status==="graded"?s.statusGoodText:s.statusPendingText]}>{sub.status==="graded"?"GRADED":"SUBMITTED"}</Text></View></View><Text style={s.meta}>Submitted {new Date(sub.submitted_at).toLocaleString()}</Text>{sub.status==="graded"?<><Text style={s.resultScore}>{sub.marks??"—"} <Text style={s.resultOutOf}>/ {a?.total_marks??"—"} marks</Text></Text><Text style={s.body}>{sub.feedback||"No written feedback from your teacher."}</Text></>:<Text style={s.body}>Your work has been received and is waiting for your teacher to review it.</Text>}</Card>})}{!studentSubmissions.length?<Text style={s.empty}>No submitted assignments yet. Submit an assignment to see your progress here.</Text>:null}</>}
